<?php
/** Bộ xếp TKB độc lập: chỉ đọc PCCM, chỉ ghi kho nháp riêng cho tới khi công bố. */
if(!function_exists('tkb_weeks'))require_once dirname(__DIR__).'/chuyenmon/includes/timetable_store.php';
if(!defined('CDS_TTB_FILE'))define('CDS_TTB_FILE',DATA_PATH.'/timetable_builder.json');
if(!defined('CDS_TTB_WORKSPACES_FILE'))define('CDS_TTB_WORKSPACES_FILE',DATA_PATH.'/timetable_workspaces.json');

function ttb_default():array{return ['enabled'=>true,'settings'=>['days'=>[2,3,4,5,6,7],'morning_periods'=>5,'afternoon_periods'=>5,'attempts'=>40,'run_seconds'=>8,'max_teacher_daily'=>7,'max_teacher_gaps'=>2,'max_teacher_days'=>6,'max_teacher_consecutive'=>5,'max_class_daily'=>10,'max_subject_class_daily'=>2,'max_subject_class_session'=>1,'avoid_edges'=>true,'optimize_teacher_days'=>true,'spread_same_subject'=>true,'prefer_morning'=>true],'blocked'=>[],'class_blocked'=>[],'scope_blocks'=>[],'special_slots'=>[],'groups'=>[],'fixed_lessons'=>[],'double_lessons'=>[],'subject_sequences'=>[],'period_overrides'=>[],'subject_rules'=>[],'subject_limit_exceptions'=>[],'plans'=>[],'active_plan'=>'','updated_at'=>''];}
function ttb_workspaces():array{$rows=load_json(CDS_TTB_WORKSPACES_FILE,[]);if(!is_array($rows)||!$rows)$rows=[['id'=>'legacy','name'=>'Phiên bản hiện tại','week_key'=>'','created_at'=>'','updated_at'=>'']];return array_values($rows);}
function ttb_workspace(string$id=''):?array{foreach(ttb_workspaces()as$row)if((string)($row['id']??'')===$id)return$row;return null;}
function ttb_workspace_id():string{$requested=trim((string)($_REQUEST['workspace']??''));if($requested!==''&&ttb_workspace($requested))$_SESSION['ttb_workspace_id']=$requested;$id=(string)($_SESSION['ttb_workspace_id']??'legacy');return ttb_workspace($id)?$id:'legacy';}
function ttb_workspace_file(string$id):string{return$id==='legacy'?CDS_TTB_FILE:DATA_PATH.'/timetable_builder_'.preg_replace('/[^a-zA-Z0-9_-]/','',$id).'.json';}
function ttb_workspace_create(string$name,string$weekKey='',string$copyFrom=''):array{$id='week_'.date('YmdHis').'_'.bin2hex(random_bytes(2));$source=$copyFrom!==''&&ttb_workspace($copyFrom)?load_json(ttb_workspace_file($copyFrom),[]):[];$data=is_array($source)&&$source?array_merge(ttb_default(),$source):ttb_default();$data['plans']=[];$data['active_plan']='';$data['updated_at']=date('c');save_json(ttb_workspace_file($id),$data);$rows=ttb_workspaces();$row=['id'=>$id,'name'=>$name!==''?$name:'Tuần làm việc '.date('d/m/Y'),'week_key'=>$weekKey,'copied_from'=>$copyFrom,'created_at'=>date('c'),'updated_at'=>date('c')];$rows[]=$row;save_json(CDS_TTB_WORKSPACES_FILE,$rows);$_SESSION['ttb_workspace_id']=$id;return$row;}
function ttb_workspace_update_meta(string$id,array$patch):void{$rows=ttb_workspaces();foreach($rows as&$row)if(($row['id']??'')===$id){$row=array_merge($row,$patch,['updated_at'=>date('c')]);break;}unset($row);save_json(CDS_TTB_WORKSPACES_FILE,$rows);}
function ttb_workspace_delete(string$id):array{if($id===''||$id==='legacy')return['ok'=>false,'message'=>'Phiên bản mặc định không thể xóa.'];$rows=ttb_workspaces();$found=null;$remaining=[];foreach($rows as$row){if((string)($row['id']??'')===$id){$found=$row;continue;}$remaining[]=$row;}if(!$found)return['ok'=>false,'message'=>'Không tìm thấy phiên bản làm việc cần xóa.'];if(!$remaining)return['ok'=>false,'message'=>'Phải giữ lại ít nhất một phiên bản làm việc.'];$file=ttb_workspace_file($id);$trash='';if(is_file($file)){$trash=$file.'.deleting_'.bin2hex(random_bytes(3));if(!@rename($file,$trash))return['ok'=>false,'message'=>'Không thể khóa tệp dữ liệu để xóa an toàn.'];}if(!save_json(CDS_TTB_WORKSPACES_FILE,array_values($remaining))){if($trash!=='')@rename($trash,$file);return['ok'=>false,'message'=>'Không thể cập nhật danh sách phiên bản; dữ liệu chưa bị xóa.'];}if((string)($_SESSION['ttb_workspace_id']??'')===$id)$_SESSION['ttb_workspace_id']=(string)($remaining[0]['id']??'legacy');if($trash!=='')@unlink($trash);return['ok'=>true,'message'=>'Đã xóa phiên bản “'.(string)($found['name']??'Phiên bản tuần').'”. TKB đã công bố không bị ảnh hưởng.'];}
function ttb_canonicalize_subject_data(array$data):array{
    foreach(['groups','fixed_lessons','subject_limit_exceptions']as$key){
        foreach($data[$key]as&$row)if(is_array($row)&&isset($row['subject']))$row['subject']=tkb_subject_canonical((string)$row['subject']);
        unset($row);
    }
    foreach($data['subject_sequences']as&$row)if(is_array($row)&&isset($row['subjects']))$row['subjects']=array_map(fn($v)=>tkb_subject_canonical((string)$v),(array)$row['subjects']);
    unset($row);
    $rules=[];foreach($data['subject_rules']as$subject=>$rule)$rules[tkb_subject_canonical((string)$subject)]=$rule;$data['subject_rules']=$rules;
    foreach($data['plans']as&$plan){
        foreach(['entries','unplaced']as$key){if(!isset($plan[$key])||!is_array($plan[$key]))continue;foreach($plan[$key]as&$entry)if(is_array($entry)&&isset($entry['subject']))$entry['subject']=tkb_subject_canonical((string)$entry['subject']);unset($entry);}
    }
    unset($plan);return$data;
}
function ttb_data():array{$base=ttb_default();$id=ttb_workspace_id();$raw=load_json(ttb_workspace_file($id),[]);if(!is_array($raw))$raw=[];$data=array_merge($base,$raw);$data['settings']=array_merge($base['settings'],is_array($raw['settings']??null)?$raw['settings']:[]);foreach(['blocked','class_blocked','scope_blocks','special_slots','groups','fixed_lessons','double_lessons','subject_sequences','period_overrides','subject_rules','subject_limit_exceptions','plans']as$key)if(!is_array($data[$key]??null))$data[$key]=[];$data=ttb_canonicalize_subject_data($data);$data['_workspace_id']=$id;$data['_workspace']=ttb_workspace($id);$GLOBALS['CDS_TTB_CURRENT_DATA']=$data;return$data;}
function ttb_save(array$data):bool{$data=ttb_canonicalize_subject_data($data);$id=(string)($data['_workspace_id']??ttb_workspace_id());unset($data['_workspace_id'],$data['_workspace']);$data['updated_at']=date('c');$ok=save_json(ttb_workspace_file($id),$data);if($ok)ttb_workspace_update_meta($id,[]);$data['_workspace_id']=$id;$data['_workspace']=ttb_workspace($id);$GLOBALS['CDS_TTB_CURRENT_DATA']=$data;return$ok;}
function ttb_pccm_dir():string{if(defined('PCCM_DATA_PATH')&&PCCM_DATA_PATH!=='')return rtrim(PCCM_DATA_PATH,'/\\');if(defined('TKB_WEEKS_FILE'))return rtrim(DATA_PATH,'/\\');return BASE_PATH.'/chuyenmon/data';}
function ttb_assignments():array{$dir=ttb_pccm_dir();$active=load_json($dir.'/active_version.json',[]);$vid=trim((string)($active['id']??''));if($vid===''){foreach((array)load_json($dir.'/versions.json',[])as$v)if(!empty($v['id'])){$vid=(string)$v['id'];break;}}$rows=$vid!==''?load_json($dir.'/assignments_'.$vid.'.json',[]):load_json($dir.'/assignments.json',[]);$manual=load_json($dir.'/manual_assignments.json',[]);foreach(is_array($manual)?$manual:[]as$r){$rv=trim((string)($r['version_id']??''));if($rv!==''&&$rv!==$vid)continue;$r['class']=$r['class']??$r['class_name']??'';$r['is_manual']=true;$rows[]=$r;}$out=[];foreach(is_array($rows)?$rows:[]as$r){$teacher=trim((string)($r['teacher']??''));$subject=tkb_subject_canonical(trim((string)($r['subject']??'')));$class=trim((string)($r['class']??$r['class_name']??''));$periods=(float)($r['periods']??0);if($teacher===''||$subject===''||$class===''||$periods<=0)continue;$id=trim((string)($r['id']??''))?:hash('sha256',$teacher.'|'.$subject.'|'.$class);$override=(array)(($GLOBALS['CDS_TTB_CURRENT_DATA']['period_overrides']??[])[$id]??[]);if(array_key_exists('periods',$override))$periods=max(0,(float)$override['periods']);$out[]=['id'=>$id,'teacher'=>$teacher,'subject'=>$subject,'class'=>$class,'periods'=>$periods,'base_periods'=>(float)($r['periods']??0),'note'=>(string)($r['note']??'')];}usort($out,fn($a,$b)=>strnatcasecmp($a['class'].'|'.$a['subject'],$b['class'].'|'.$b['subject']));return$out;}
function ttb_slot_key(int$day,string$session,int$period):string{return$day.'|'.$session.'|'.$period;}
function ttb_slots(array$settings):array{$out=[];foreach((array)($settings['days']??[2,3,4,5,6,7])as$day){foreach(['Sáng'=>(int)($settings['morning_periods']??5),'Chiều'=>(int)($settings['afternoon_periods']??5)]as$session=>$max)for($p=1;$p<=$max;$p++)$out[]=['day'=>(int)$day,'session'=>$session,'period'=>$p,'key'=>ttb_slot_key((int)$day,$session,$p)];}return$out;}
function ttb_group_map(array$groups):array{$map=[];foreach($groups as$g)foreach((array)($g['assignment_ids']??[])as$id)$map[(string)$id]=(string)($g['id']??'');return$map;}
function ttb_activities(array$assignments,array$groups):array{$byId=[];foreach($assignments as$a)$byId[$a['id']]=$a;$consumed=[];$out=[];
 foreach($groups as$g){$members=[];foreach((array)($g['assignment_ids']??[])as$id)if(isset($byId[$id]))$members[]=$byId[$id];if(count($members)<2)continue;$available=min(array_map(fn($m)=>max(0,(int)round($m['periods'])-(int)($consumed[$m['id']]??0)),$members));$count=min(max(1,(int)($g['periods']??1)),$available);if($count<1)continue;foreach($members as$m)$consumed[$m['id']]=(int)($consumed[$m['id']]??0)+$count;for($n=1;$n<=$count;$n++)$out[]=['id'=>(string)$g['id'].'_'.$n,'group_id'=>(string)$g['id'],'teacher'=>(string)($g['teacher']??$members[0]['teacher']),'subject'=>(string)($g['subject']??$members[0]['subject']),'classes'=>array_values(array_unique(array_column($members,'class'))),'fixed_day'=>(int)($g['day']??0),'fixed_session'=>(string)($g['session']??''),'fixed_period'=>(int)($g['period']??0),'credit_mode'=>(string)($g['credit_mode']??'per_class')];}
 foreach($assignments as$a){$remaining=max(0,(int)round($a['periods'])-(int)($consumed[$a['id']]??0));for($n=1;$n<=$remaining;$n++)$out[]=['id'=>$a['id'].'_'.$n,'assignment_id'=>$a['id'],'teacher'=>$a['teacher'],'subject'=>$a['subject'],'classes'=>[$a['class']],'fixed_day'=>0,'fixed_session'=>'','fixed_period'=>0,'credit_mode'=>'per_class'];}
 return$out;}
function ttb_apply_lesson_rules(array$activities,array$data):array{$fixed=(array)($data['fixed_lessons']??[]);$subjectRules=(array)($data['subject_rules']??[]);foreach($activities as&$a){$subjectRule=(array)($subjectRules[(string)$a['subject']]??[]);$a['allowed_session']=(string)($subjectRule['session']??'');$a['allowed_period_from']=max(0,(int)($subjectRule['period_from']??0));$a['allowed_period_to']=max(0,(int)($subjectRule['period_to']??0));$a['sequence_rules']=[];foreach((array)($data['subject_sequences']??[])as$sequence){$ordered=array_values(array_map('strval',(array)($sequence['subjects']??[])));$index=array_search((string)$a['subject'],$ordered,true);if($index===false)continue;$scope=(string)($sequence['scope']??'school');$value=(string)($sequence['value']??'');$matched=[];foreach((array)$a['classes']as$class)if($scope==='school'||($scope==='class'&&(string)$class===$value)||($scope==='grade'&&ttb_class_grade((string)$class)===(ltrim($value,'0')?:'0')))$matched[]=(string)$class;if($matched)$a['sequence_rules'][]=['id'=>(string)($sequence['id']??''),'index'=>(int)$index,'subjects'=>$ordered,'classes'=>$matched];}$rule=(array)($fixed[$a['id']]??[]);if($rule){$a['fixed_day']=(int)($rule['day']??0);$a['fixed_session']=(string)($rule['session']??'');$a['fixed_period']=(int)($rule['period']??0);}}unset($a);$byAssignment=[];foreach($activities as$i=>$a)if(!empty($a['assignment_id']))$byAssignment[(string)$a['assignment_id']][]=$i;foreach((array)($data['double_lessons']??[])as$assignmentId=>$rule){$pairs=max(0,(int)($rule['pairs']??0));$indexes=$byAssignment[(string)$assignmentId]??[];for($p=0;$p<$pairs;$p++){if(!isset($indexes[$p*2+1]))break;$pairId='dbl_'.hash('sha256',$assignmentId.'|'.$p);$activities[$indexes[$p*2]]['pair_id']=$pairId;$activities[$indexes[$p*2]]['pair_order']=1;$activities[$indexes[$p*2+1]]['pair_id']=$pairId;$activities[$indexes[$p*2+1]]['pair_order']=2;}}return$activities;}
function ttb_blocked(array$data,string$teacher,string$key):bool{return!empty($data['blocked'][hash('sha256',$teacher.'|'.$key)]);}
function ttb_class_blocked(array$data,array$classes,string$key):bool{foreach($classes as$class)if(!empty($data['class_blocked'][hash('sha256',$class.'|'.$key)]))return true;return false;}
function ttb_class_grade(string$class):string{if(preg_match('/\d+/u',$class,$m))return ltrim($m[0],'0')?:'0';return'';}
function ttb_scope_blocked(array$data,array$classes,string$key):bool{foreach((array)($data['scope_blocks']??[])as$rule){if((string)($rule['key']??'')!==$key)continue;$scope=(string)($rule['scope']??'school');$value=trim((string)($rule['value']??''));if($scope==='school')return true;foreach($classes as$class){$class=(string)$class;if($scope==='class'&&trim($class)===$value)return true;if($scope==='grade'&&ttb_class_grade($class)===(ltrim($value,'0')?:'0'))return true;}}return false;}
function ttb_slot_unavailable(array$data,array$a,array$s):bool{$key=(string)$s['key'];return ttb_blocked($data,(string)$a['teacher'],$key)||ttb_class_blocked($data,(array)$a['classes'],$key)||ttb_scope_blocked($data,(array)$a['classes'],$key);}
function ttb_slot_rank(array$s):int{$session=(string)($s['session']??'')==='Chiều'?1:0;return(int)($s['day']??0)*100+$session*20+(int)($s['period']??0);}
function ttb_sequence_candidate_error(array$a,array$s,array$entries):?string{$rank=ttb_slot_rank($s);foreach((array)($a['sequence_rules']??[])as$rule){$ruleId=(string)($rule['id']??'');$index=(int)($rule['index']??0);$classes=(array)($rule['classes']??[]);foreach($entries as$entry){if(!array_intersect($classes,(array)($entry['classes']??[])))continue;foreach((array)($entry['sequence_rules']??[])as$other){if((string)($other['id']??'')!==$ruleId)continue;$otherIndex=(int)($other['index']??0);$otherRank=ttb_slot_rank($entry);if(($otherIndex<$index&&$otherRank>=$rank)||($otherIndex>$index&&$otherRank<=$rank))return'Thứ tự môn '.implode(' → ',(array)($rule['subjects']??[])).' chưa đúng';}}}return null;}
function ttb_subject_limits(array$data,string$subject):array{$daily=max(1,(int)($data['settings']['max_subject_class_daily']??2));$session=max(1,(int)($data['settings']['max_subject_class_session']??1));$exception=(array)(($data['subject_limit_exceptions']??[])[$subject]??[]);if($exception){$daily=max(1,(int)($exception['daily']??$daily));$session=max(1,(int)($exception['session']??$session));}return['daily'=>$daily,'session'=>min($daily,$session),'exception'=>(bool)$exception];}
function ttb_subject_limit_error(array$data,array$a,array$s,array$entries,array$ignore=[]):?string{$limits=ttb_subject_limits($data,(string)$a['subject']);$ignored=array_fill_keys(array_map('strval',$ignore),true);foreach((array)$a['classes']as$class){$daily=0;$session=0;foreach($entries as$e){if(isset($ignored[(string)($e['activity_id']??'')])||($e['subject']??'')!==$a['subject']||!in_array($class,(array)($e['classes']??[]),true)||(int)($e['day']??0)!==(int)$s['day'])continue;$daily++;if(($e['session']??'')===$s['session'])$session++;}if($daily>=$limits['daily'])return'Môn '.$a['subject'].' lớp '.$class.' đã đủ '.$limits['daily'].' tiết/ngày';if($session>=$limits['session'])return'Môn '.$a['subject'].' lớp '.$class.' đã đủ '.$limits['session'].' tiết/buổi';}$sequenceError=ttb_sequence_candidate_error($a,$s,$entries);return$sequenceError;}
function ttb_subject_constraint_errors(array$data,array$entries):array{$errors=[];$daily=[];$sessions=[];foreach($entries as$e)foreach((array)($e['classes']??[])as$class){$base=(string)$class.'|'.(string)$e['subject'].'|'.(int)$e['day'];$daily[$base]=($daily[$base]??0)+1;$sessionKey=$base.'|'.(string)$e['session'];$sessions[$sessionKey]=($sessions[$sessionKey]??0)+1;$limits=ttb_subject_limits($data,(string)$e['subject']);if($daily[$base]>$limits['daily'])$errors[]='Vượt '.$limits['daily'].' tiết/ngày: '.$e['subject'].' lớp '.$class;if($sessions[$sessionKey]>$limits['session'])$errors[]='Vượt '.$limits['session'].' tiết/buổi: '.$e['subject'].' lớp '.$class;}return array_values(array_unique($errors));}
function ttb_compact_cost(array$periods):int{$periods=array_values(array_unique(array_map('intval',$periods)));if(!$periods)return 0;sort($periods);return max(0,max($periods)-count($periods));}
function ttb_adjacent_same_subject(array$a,array$s,array$placed):bool{foreach($placed as$p){if((int)($p['day']??0)!==(int)($s['day']??0)||(string)($p['session']??'')!==(string)($s['session']??'')||abs((int)($p['period']??0)-(int)($s['period']??0))!==1||(string)($p['subject']??'')!==(string)($a['subject']??''))continue;if(!array_intersect((array)($p['classes']??[]),(array)($a['classes']??[])))continue;$pair=(string)($a['pair_id']??'');if($pair!==''&&$pair===(string)($p['pair_id']??''))continue;return true;}return false;}
function ttb_candidate_score(array$a,array$s,array$placed,array$settings):int{$score=random_int(0,2);if(!empty($settings['prefer_morning'])&&$s['session']==='Chiều')$score+=5000;$teacher=$a['teacher'];$day=$s['day'];$sameTeacherDay=[];$teacherDays=[];$sameSubjectDay=0;$classDay=0;$sameClassSession=[];foreach($placed as$p){if($p['teacher']===$teacher){$teacherDays[$p['day']]=true;if($p['day']===$day)$sameTeacherDay[]=$p;}if($p['day']===$day&&array_intersect($p['classes'],$a['classes'])){$classDay++;if($p['session']===$s['session'])$sameClassSession[]=(int)$p['period'];if($p['subject']===$a['subject'])$sameSubjectDay++;}}$score+=max(0,$sameSubjectDay+1-(int)($settings['max_subject_class_daily']??2))*180;if(!empty($settings['spread_same_subject']))$score+=$sameSubjectDay*25;$score+=max(0,$classDay+1-(int)($settings['max_class_daily']??10))*500;$classPeriods=$sameClassSession;$classPeriods[]=(int)$s['period'];$score+=ttb_compact_cost($classPeriods)*420;$score+=max(0,count($sameTeacherDay)+1-(int)($settings['max_teacher_daily']??7))*500;if(!isset($teacherDays[$day])&&count($teacherDays)>=(int)($settings['max_teacher_days']??6))$score+=600;if(!empty($settings['optimize_teacher_days'])&&!isset($teacherDays[$day])&&$teacherDays)$score+=10;$teacherPeriods=array_column(array_filter($sameTeacherDay,fn($p)=>$p['session']===$s['session']),'period');$teacherPeriods[]=(int)$s['period'];$score+=ttb_compact_cost($teacherPeriods)*260;if(count($teacherPeriods)>1){sort($teacherPeriods);$run=1;$best=1;for($i=1;$i<count($teacherPeriods);$i++){$run=$teacherPeriods[$i]===$teacherPeriods[$i-1]+1?$run+1:1;$best=max($best,$run);}$score+=max(0,$best-(int)($settings['max_teacher_consecutive']??5))*250;}if(!empty($settings['avoid_edges'])){$maxPeriod=$s['session']==='Sáng'?(int)$settings['morning_periods']:(int)$settings['afternoon_periods'];if($s['period']===$maxPeriod)$score+=8;}return$score;}
function ttb_global_penalty(array$entries,array$settings):int{$byTeacher=[];$byClass=[];foreach($entries as$e){$byTeacher[(string)$e['teacher']][(int)$e['day']][(string)$e['session']][]=(int)$e['period'];foreach((array)$e['classes']as$class)$byClass[(string)$class][(int)$e['day']][(string)$e['session']][]=(int)$e['period'];}$penalty=0;$gapLimit=max(0,(int)($settings['max_teacher_gaps']??2));foreach($byTeacher as$days)foreach($days as$sessions)foreach($sessions as$periods){$compact=ttb_compact_cost($periods);$internal=0;$unique=array_values(array_unique($periods));sort($unique);if(count($unique)>1)$internal=max($unique)-min($unique)+1-count($unique);$penalty+=$compact*420+max(0,$internal-$gapLimit)*600;}foreach($byClass as$days)foreach($days as$sessions)foreach($sessions as$periods)$penalty+=ttb_compact_cost($periods)*700;return$penalty;}
function ttb_validate_entries(array$entries,array$activities):array{$errors=[];$classBusy=[];$teacherBusy=[];$activityMap=[];$pairEntries=[];foreach($activities as$a)$activityMap[$a['id']]=$a;foreach($entries as$i=>$e){$rule=(array)($activityMap[(string)($e['activity_id']??'')]??[]);$e=array_merge($rule,$e);$entries[$i]=$e;if(!empty($rule['fixed_day'])&&((int)$e['day']!==(int)$rule['fixed_day']||(!empty($rule['fixed_session'])&&$e['session']!==$rule['fixed_session'])||(!empty($rule['fixed_period'])&&(int)$e['period']!==(int)$rule['fixed_period'])))$errors[]='Tiết cố định đã bị chuyển sai vị trí: '.$e['subject'].' '.implode('+',(array)$e['classes']);$key=ttb_slot_key((int)$e['day'],(string)$e['session'],(int)$e['period']);$aid=(string)$e['activity_id'];foreach((array)$e['classes']as$c){$ck=$c.'|'.$key;if(isset($classBusy[$ck])&&$classBusy[$ck]!==$aid)$errors[]='Trùng lớp '.$c.' tại '.$key;$classBusy[$ck]=$aid;}if(!empty($e['pair_id']))$pairEntries[(string)$e['pair_id']][]=$e;$tk=$e['teacher'].'|'.$key;if(isset($teacherBusy[$tk])&&$teacherBusy[$tk]!==$aid)$errors[]='Trùng giáo viên '.$e['teacher'].' tại '.$key;$teacherBusy[$tk]=$aid;}foreach($pairEntries as$pairId=>$pair){if(count($pair)!==2){$errors[]='Cặp tiết liền nhau chưa đủ: '.$pairId;continue;}$a=$pair[0];$b=$pair[1];if($a['day']!==$b['day']||$a['session']!==$b['session']||abs((int)$a['period']-(int)$b['period'])!==1)$errors[]='Hai tiết bắt buộc liền nhau đã bị tách: '.$a['subject'].' '.implode('+',(array)$a['classes']);}foreach($entries as$i=>$entry)if(($message=ttb_sequence_candidate_error($entry,$entry,array_slice($entries,0,$i)))!==null)$errors[]=$message;return array_values(array_unique($errors));}
