  foreach($todo as$a){$candidates=[];foreach($slots as$s){if(!empty($a['allowed_session'])&&$s['session']!==$a['allowed_session'])continue;if(!empty($a['allowed_period_from'])&&$s['period']<(int)$a['allowed_period_from'])continue;if(!empty($a['allowed_period_to'])&&$s['period']>(int)$a['allowed_period_to'])continue;if($a['fixed_day']&&($s['day']!==$a['fixed_day']||($a['fixed_session']!==''&&$s['session']!==$a['fixed_session'])||($a['fixed_period']&&$s['period']!==$a['fixed_period'])))continue;if(ttb_slot_unavailable($data,$a,$s))continue;if(!empty($a['pair_id'])){$partner=null;foreach($placed as$p)if(($p['pair_id']??'')===$a['pair_id']){$partner=$p;break;}if($partner){if($s['day']!==$partner['day']||$s['session']!==$partner['session']||abs($s['period']-$partner['period'])!==1)continue;}else{$maxPair=$s['session']==='Sáng'?(int)$settings['morning_periods']:(int)$settings['afternoon_periods'];$pairSpace=false;foreach([$s['period']-1,$s['period']+1]as$near){if($near<1||$near>$maxPair)continue;$nearKey=ttb_slot_key($s['day'],$s['session'],$near);if(ttb_slot_unavailable($data,$a,['key'=>$nearKey])||isset($teacherBusy[$a['teacher'].'|'.$nearKey]))continue;$pairBad=false;foreach($a['classes']as$c)if(isset($classBusy[$c.'|'.$nearKey])){$pairBad=true;break;}if(!$pairBad){$pairSpace=true;break;}}if(!$pairSpace)continue;}}if(isset($teacherBusy[$a['teacher'].'|'.$s['key']]))continue;$bad=false;foreach($a['classes']as$c)if(isset($classBusy[$c.'|'.$s['key']])){$bad=true;break;}if($bad)continue;if(ttb_subject_limit_error($data,$a,$s,$placed)!==null)continue;if(ttb_adjacent_same_subject($a,$s,$placed))continue;$candidates[]=['slot'=>$s,'score'=>ttb_candidate_score($a,$s,$placed,$settings)];}if(!$candidates){$unplaced[]=$a;continue;}usort($candidates,fn($x,$y)=>$x['score']<=>$y['score']);$pick=$candidates[0];$s=$pick['slot'];$entry=array_merge($a,['activity_id'=>$a['id'],'day'=>$s['day'],'session'=>$s['session'],'period'=>$s['period'],'locked'=>false]);$placed[]=$entry;$score+=$pick